<style>
.ct-statement-document{color:#20334d;background:#fff;font-size:14px;line-height:1.5}
.ct-statement-document .statement-brand{width:100%;border-collapse:collapse;border-bottom:3px solid #183858;margin-bottom:22px}
.ct-statement-document .statement-brand td{vertical-align:middle;padding:0 0 18px}
.ct-statement-document .statement-brand-logo{width:58px;height:58px;vertical-align:middle;margin-right:12px}
.ct-statement-document .statement-brand-name{font-size:24px;font-weight:700;letter-spacing:.2px}
.ct-statement-document .statement-title{text-align:right;font-size:25px;font-weight:700;line-height:1.2}
.ct-statement-document .statement-kicker{font-size:10px;text-transform:uppercase;letter-spacing:1.4px;color:#60728a;font-weight:700}
.ct-statement-document .statement-meta{width:100%;border-collapse:collapse;margin-bottom:22px;table-layout:fixed}
.ct-statement-document .statement-meta td{vertical-align:top;width:50%;padding:0 20px 0 0;overflow-wrap:anywhere}
.ct-statement-document .statement-meta strong{display:block;font-size:16px;margin:4px 0}
.ct-statement-document .statement-meta dl{margin:0}
.ct-statement-document .statement-meta dt{font-weight:400;color:#60728a;display:inline}
.ct-statement-document .statement-meta dd{display:inline;margin:0;font-weight:600}
.ct-statement-document .statement-summary{width:100%;table-layout:fixed;border-collapse:collapse;margin:12px 0 8px}
.ct-statement-document .statement-summary td{padding:15px;border:1px solid #d9e2ec;background:#f4f7fa;vertical-align:top}
.ct-statement-document .statement-summary-label{display:block;color:#52657c;font-size:12px;margin-bottom:5px}
.ct-statement-document .statement-value{display:block;font-size:23px;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}
.ct-statement-document .statement-summary .statement-net{background:#eaf1f7;color:#173b5e}
.ct-statement-document .statement-section{margin-top:26px}
.ct-statement-document .statement-section-title{font-size:16px;font-weight:700;margin:0 0 5px;color:#183858}
.ct-statement-document .statement-caption{font-size:12px;color:#60728a;margin:0 0 12px}
.ct-statement-document .statement-table{width:100%;min-width:720px;table-layout:fixed;border-collapse:collapse;margin:0;font-size:12px}
.ct-statement-document .statement-table th{background:#eaf0f6;color:#183858;text-transform:uppercase;letter-spacing:.4px;font-size:10px;font-weight:700;text-align:left}
.ct-statement-document .statement-table th,.ct-statement-document .statement-table td{padding:10px 9px;border-bottom:1px solid #dce4ed;vertical-align:top;overflow-wrap:break-word;word-wrap:break-word}
.ct-statement-document .statement-table tbody tr:nth-child(even){background:#fafbfd}
.ct-statement-document .statement-money{font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap;font-weight:600}
.ct-statement-document .statement-reference{font-size:11px;color:#53677e}
.ct-statement-document .entry-detail{margin-bottom:9px}.ct-statement-document .entry-detail:last-child{margin-bottom:0}
.ct-statement-document .statement-table small{font-size:10px;color:#61718a}
.ct-statement-document .statement-empty{padding:18px;color:#60728a}
.ct-statement-document .statement-unavailable{color:#80632c;font-size:11px;font-weight:400;white-space:normal}
.ct-statement-document .statement-fee-source{color:#52657c;font-size:10px;line-height:1.4;display:block;margin-top:4px;white-space:normal}
.ct-statement-document .statement-fee-summary{border:1px solid #dce4ed;background:#f7f9fb;padding:12px 14px;margin:12px 0}
.ct-statement-document .statement-fee-summary p{margin:3px 0;font-size:12px}
.ct-statement-document .statement-fee-summary strong{color:#183858}
.ct-statement-document .statement-notice{background:#fff9ed;border-left:3px solid #cda04f;padding:10px 13px;margin:14px 0;color:#655332;font-size:11px}
.ct-statement-document .statement-notice p{margin:3px 0}
.ct-statement-document .statement-notes{font-size:10px;line-height:1.5;color:#60728a;border-top:1px solid #dce4ed;margin-top:22px;padding-top:12px}
.ct-statement-document .statement-notes p{margin:0 0 6px}
.ct-statement-document .statement-right{text-align:right}.ct-statement-document .statement-footer{font-size:10px;color:#60728a;margin-top:12px}
@media(max-width:575.98px){
 .ct-statement-document .statement-brand-name{font-size:18px}.ct-statement-document .statement-title{font-size:20px}
 .ct-statement-document .statement-brand-logo{width:42px;height:42px;margin-right:6px}
 .ct-statement-document .statement-meta,.ct-statement-document .statement-meta tbody,.ct-statement-document .statement-meta tr,.ct-statement-document .statement-meta td{display:block;width:100%}
 .ct-statement-document .statement-meta td{padding:0 0 12px}
 .ct-statement-document .statement-summary,.ct-statement-document .statement-summary tbody,.ct-statement-document .statement-summary tr,.ct-statement-document .statement-summary td{display:block;width:100%}
 .ct-statement-document .statement-summary td{padding:10px 14px}.ct-statement-document .statement-value{font-size:21px}
}
@media print{.statement-controls,.statement-pagination{display:none!important}.ct-statement-document{box-shadow:none!important;border:0!important}.ct-statement-document .statement-table{min-width:0}}
</style>
